/* Base layer added by the React export: page colors, fonts and the default border color. */
@layer base {
  *,
  ::before,
  ::after,
  ::backdrop,
  ::file-selector-button {
    border-color: var(--border-default);
  }
  :root {
    color-scheme: light;
  }
  [data-theme="dark"], .dark {
    color-scheme: dark;
  }
  body {
    background-color: var(--bg-canvas);
    color: var(--text-primary);
    font-family: var(--font-body);
  }
}

/* ------------------------------------------------------------------------------------------------
 * UIX motion: enter/exit, press and focus animation for every component, keyed on data-slot.
 * Pure CSS (@starting-style, allow-discrete, ::details-content); no JS, no animation library.
 * Off for people who ask for reduced motion. Delete this block for a still UI.
 * ---------------------------------------------------------------------------------------------- */
:root {
  --uix-ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --uix-ease-spring: cubic-bezier(0.34, 1.4, 0.64, 1);
  --uix-fast: 140ms;
  --uix-base: 220ms;
  --uix-slow: 360ms;
  interpolate-size: allow-keywords;
}

@media (prefers-reduced-motion: no-preference) {
  /* Press and hover: controls give way a little under the pointer. */
  :where([data-slot="button"], [data-slot="icon-button"], [data-slot="chip"], [data-slot="toggle"], [data-slot="link"],
    [data-slot="menu-item"], [role="tab"], [role="option"], [data-slot="date-picker"] button, [data-slot="pagination"] button,
    [data-slot="segmented"] span, [data-slot="selection-card"], [data-slot="rating"] button) {
    transition-property: color, background-color, border-color, outline-color, box-shadow, opacity, transform, translate, scale;
    transition-duration: var(--uix-fast);
    transition-timing-function: var(--uix-ease-out);
  }
  :where([data-slot="button"], [data-slot="icon-button"], [data-slot="chip"], [data-slot="toggle"], [data-slot="date-picker"] button,
    [data-slot="pagination"] button, [data-slot="rating"] button):not(:disabled):active { scale: 0.96; }
  :where([data-slot="selection-card"]):hover { translate: 0 -2px; }
  :where([data-slot="rating"] button):hover { scale: 1.15; }

  /* Fields: the focus ring grows in instead of snapping. */
  :where([data-kind="field"]) { transition-property: color, background-color, border-color, box-shadow; transition-duration: var(--uix-base); }

  /* Switch knob and checkbox tick: a small spring. */
  :where([data-slot="switch"]) + span, :where([data-slot="switch"]) ~ span { transition: translate var(--uix-base) var(--uix-ease-spring), transform var(--uix-base) var(--uix-ease-spring), background-color var(--uix-base); }
  :where([data-slot="checkbox"], [data-slot="radio"]):checked + span svg,
  :where([data-slot="checkbox"], [data-slot="radio"]):checked + span { animation: uix-pop var(--uix-base) var(--uix-ease-spring); }

  /* Dialogs: modal and command palette rise and scale, drawers slide from their side, sheets from the bottom. */
  dialog:where([data-slot="modal"], [data-slot="command-palette"], [data-slot="drawer"], [data-slot="sheet"]) {
    transition: opacity var(--uix-base) var(--uix-ease-out), translate var(--uix-slow) var(--uix-ease-out), scale var(--uix-slow) var(--uix-ease-out),
      overlay var(--uix-slow) allow-discrete, display var(--uix-slow) allow-discrete;
    opacity: 0;
  }
  dialog:where([data-slot="modal"], [data-slot="command-palette"]) { translate: 0 12px; scale: 0.96; }
  dialog:where([data-slot="drawer"]) { translate: 100% 0; opacity: 1; }
  dialog:where([data-slot="drawer"].left-0) { translate: -100% 0; }
  dialog:where([data-slot="sheet"]) { translate: 0 100%; opacity: 1; }
  dialog:where([data-slot="modal"], [data-slot="command-palette"], [data-slot="drawer"], [data-slot="sheet"])[open] { opacity: 1; translate: 0 0; scale: 1; }
  @starting-style {
    dialog:where([data-slot="modal"], [data-slot="command-palette"])[open] { opacity: 0; translate: 0 12px; scale: 0.96; }
    dialog:where([data-slot="drawer"])[open] { translate: 100% 0; }
    dialog:where([data-slot="drawer"].left-0)[open] { translate: -100% 0; }
    dialog:where([data-slot="sheet"])[open] { translate: 0 100%; }
  }
  dialog:where([data-slot="modal"], [data-slot="command-palette"], [data-slot="drawer"], [data-slot="sheet"])::backdrop {
    transition: opacity var(--uix-slow) var(--uix-ease-out), overlay var(--uix-slow) allow-discrete, display var(--uix-slow) allow-discrete;
    opacity: 0;
  }
  dialog:where([data-slot="modal"], [data-slot="command-palette"], [data-slot="drawer"], [data-slot="sheet"])[open]::backdrop { opacity: 1; }
  @starting-style {
    dialog:where([data-slot="modal"], [data-slot="command-palette"], [data-slot="drawer"], [data-slot="sheet"])[open]::backdrop { opacity: 0; }
  }

  /* Popovers, menus and dropdown lists: fade and drop in from their trigger. */
  :where([data-slot="popover"]) {
    transition: opacity var(--uix-base) var(--uix-ease-out), translate var(--uix-base) var(--uix-ease-out), scale var(--uix-base) var(--uix-ease-out),
      overlay var(--uix-base) allow-discrete, display var(--uix-base) allow-discrete;
    opacity: 0; translate: 0 -4px; scale: 0.97;
  }
  :where([data-slot="popover"]):popover-open { opacity: 1; translate: 0 0; scale: 1; }
  @starting-style { :where([data-slot="popover"]):popover-open { opacity: 0; translate: 0 -4px; scale: 0.97; } }
  :where([data-slot="menu"], [role="listbox"][data-kind="overlay"]) {
    transition: opacity var(--uix-base) var(--uix-ease-out), translate var(--uix-base) var(--uix-ease-out), scale var(--uix-base) var(--uix-ease-out);
    transform-origin: top;
  }
  @starting-style { :where([data-slot="menu"], [role="listbox"][data-kind="overlay"]) { opacity: 0; translate: 0 -4px; scale: 0.97; } }

  /* Tooltips: a short lift with the existing fade. */
  :where([data-slot="tooltip"]) [role="tooltip"] { transition: opacity var(--uix-fast) var(--uix-ease-out), translate var(--uix-fast) var(--uix-ease-out); }

  /* Things that appear: toasts slide up, alerts and banners fade in, tab panels settle. */
  :where([data-slot="toast"]) { transition: opacity var(--uix-base), translate var(--uix-slow) var(--uix-ease-spring); }
  @starting-style { :where([data-slot="toast"]) { opacity: 0; translate: 0 16px; } }
  :where([data-slot="alert"], [data-slot="banner"], [data-slot="notification"], [role="tabpanel"], [data-slot="empty-state"]) {
    transition: opacity var(--uix-base) var(--uix-ease-out), translate var(--uix-base) var(--uix-ease-out);
  }
  @starting-style { :where([data-slot="alert"], [data-slot="banner"], [data-slot="notification"], [role="tabpanel"], [data-slot="empty-state"]) { opacity: 0; translate: 0 6px; } }

  /* Accordion: the panel opens to its own height (Chrome 131+; elsewhere it just opens). */
  :where([data-slot="accordion"])::details-content {
    block-size: 0; overflow-y: clip;
    transition: block-size var(--uix-slow) var(--uix-ease-out), content-visibility var(--uix-slow) allow-discrete;
  }
  :where([data-slot="accordion"])[open]::details-content { block-size: auto; }

  /* Progress fills ease to their value; spinners and skeletons keep their own loops. */
  :where([data-slot="progress"]) > div { transition: width var(--uix-slow) var(--uix-ease-out); }
  :where([data-slot="progress-circle"]) circle { transition: stroke-dashoffset var(--uix-slow) var(--uix-ease-out); }
}

@keyframes uix-pop { 0% { scale: 0.6; } 60% { scale: 1.12; } 100% { scale: 1; } }
